package com.narudzbine.identity.infrastructure.web;
import static org.assertj.core.api.Assertions.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
class OrderCursorsTest {
 private final Instant now=Instant.parse("2026-10-19T12:00:00Z");private final UUID organization=UUID.randomUUID(),order=UUID.randomUUID();
 private final OrderHistoryRequests.Filters filters=new OrderHistoryRequests.Filters("AWAITING_ACCEPTANCE",UUID.randomUUID(),LocalDate.of(2026,1,1),LocalDate.of(2026,12,31));
 private String key(int value){byte[] k=new byte[32];Arrays.fill(k,(byte)value);return Base64.getEncoder().encodeToString(k);}
 private OrderCursors codec(int n,Instant at){return new OrderCursors(key(n),"","",Clock.fixed(at,ZoneOffset.UTC));}
 private String token(){return codec(1,now).encode("LIST",organization,null,filters,25,new OrderCursors.Position(now,order,now.plusSeconds(86400)));}
 @Test void scopeFiltersSortViewTargetAndSizeAreSigned(){var c=codec(1,now);String t=token();assertThat(c.decode(t,"LIST",organization,null,filters,25).id()).isEqualTo(order);assertThatThrownBy(()->c.decode(t,"LIST",UUID.randomUUID(),null,filters,25)).isInstanceOf(AuthHttpFailure.class);assertThatThrownBy(()->c.decode(t,"EVENTS",organization,null,filters,25)).isInstanceOf(AuthHttpFailure.class);assertThatThrownBy(()->c.decode(t,"LIST",organization,order,filters,25)).isInstanceOf(AuthHttpFailure.class);assertThatThrownBy(()->c.decode(t,"LIST",organization,null,filters,1)).isInstanceOf(AuthHttpFailure.class);for(var f:List.of(new OrderHistoryRequests.Filters(null,filters.partner(),filters.from(),filters.to()),new OrderHistoryRequests.Filters(filters.state(),null,filters.from(),filters.to()),new OrderHistoryRequests.Filters(filters.state(),filters.partner(),null,filters.to()),new OrderHistoryRequests.Filters(filters.state(),filters.partner(),filters.from(),null))){assertThatThrownBy(()->c.decode(t,"LIST",organization,null,f,25)).isInstanceOf(AuthHttpFailure.class);}}
 @Test void expiryAndTamperingRejectWithoutExtendingLifetime(){assertThatThrownBy(()->codec(1,now.plusSeconds(86400)).decode(token(),"LIST",organization,null,filters,25)).isInstanceOf(AuthHttpFailure.class);var c=codec(1,now);for(String bad:List.of(token()+"x","v1.bad.bad.bad","",token().replace("v1.","v2."))){assertThatThrownBy(()->c.decode(bad,"LIST",organization,null,filters,25)).isInstanceOf(AuthHttpFailure.class);}assertThat(codec(1,now.plusSeconds(100)).decode(token(),"LIST",organization,null,filters,25).expires()).isEqualTo(now.plusSeconds(86400));}
 @Test void previousKeyHonorsExplicitRetirementAndWrongKeysReject(){var until=now.plusSeconds(600);var c=new OrderCursors(key(2),key(1),until.toString(),Clock.fixed(now,ZoneOffset.UTC));assertThat(c.decode(token(),"LIST",organization,null,filters,25).id()).isEqualTo(order);assertThatThrownBy(()->new OrderCursors(key(2),key(1),until.toString(),Clock.fixed(until,ZoneOffset.UTC)).decode(token(),"LIST",organization,null,filters,25)).isInstanceOf(AuthHttpFailure.class);assertThatThrownBy(()->codec(2,now).decode(token(),"LIST",organization,null,filters,25)).isInstanceOf(AuthHttpFailure.class);}
 @Test void incompleteOrOverlongRotationConfigurationRejects(){assertThatThrownBy(()->new OrderCursors(key(2),key(1),now.plusSeconds(86401).toString(),Clock.fixed(now,ZoneOffset.UTC))).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->new OrderCursors(key(2),key(1),"",Clock.fixed(now,ZoneOffset.UTC))).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->new OrderCursors(key(2),"",now.toString(),Clock.fixed(now,ZoneOffset.UTC))).isInstanceOf(IllegalArgumentException.class);}
 @Test void eventCursorBindsItsTargetAndCannotBecomeAListCursor(){var c=codec(1,now);var empty=new OrderHistoryRequests.Filters(null,null,null,null);String t=c.encode("EVENTS",organization,order,empty,25,new OrderCursors.Position(now,UUID.randomUUID(),now.plusSeconds(86400)));assertThat(c.decode(t,"EVENTS",organization,order,empty,25).at()).isEqualTo(now);assertThatThrownBy(()->c.decode(t,"EVENTS",organization,UUID.randomUUID(),empty,25)).isInstanceOf(AuthHttpFailure.class);assertThatThrownBy(()->c.decode(t,"LIST",organization,null,empty,25)).isInstanceOf(AuthHttpFailure.class);}

}
